struct Matrix{int N,K;std::vector<int8_t> t;std::vector<uint16_t> scales;std::array<uint8_t*,2> image{};uint8_t* ds=nullptr;};
Matrix read_matrix(h5::Gguf& gg,const std::vector<std::string>& names){Matrix m{};m.K=gg.t(names[0]).ne.at(0);int rows=gg.t(names[0]).ne.at(1);m.N=rows*names.size();m.t.resize((size_t)m.N*m.K);m.scales.resize((size_t)m.N*m.K/128);int B=m.K/128,G=m.N/32;for(int n=0;n<(int)names.size();n++){auto& t=gg.t(names[n]);if(t.type!=143||t.ne.at(0)!=(unsigned)m.K||t.ne.at(1)!=(unsigned)rows||t.bytes!=(size_t)rows*B*28)exit(2);for(int row=0;row<rows;row++){int dst=names.size()==2?(row/32)*64+n*32+row%32:row;for(int kb=0;kb<B;kb++){uint16_t sc;dense5::decode_ptq(t.data+((size_t)row*B+kb)*28,m.t.data()+(size_t)dst*m.K+kb*128,sc);int gid=dst%8,mm=(dst%32)/16,r=(dst%16)/8,g=dst/32;m.scales[((size_t)kb*G+g)*32+gid*4+mm*2+r]=sc;}}}m.ds=(uint8_t*)device(m.scales);return m;}
void packet_values(const Matrix& m,int g,int kb,int lane,int w,int side,int8_t* v){int gid=lane>>2,tq=lane&3,mm=w>>2,h=(w>>1)&1,r=w&1,row=g*32+mm*16+r*8+gid;for(int j=0;j<8;j++)v[j]=m.t[(size_t)row*m.K+kb*128+64*h+32*side+8*tq+j];}
void pack(Matrix& m){int G=m.N/32,B=m.K/128;for(int image=0;image<2;image++){int cw=image==0?1024:832;std::vector<uint8_t> b((size_t)G*B*cw);for(int kb=0;kb<B;kb++)for(int g=0;g<G;g++){uint8_t* p=b.data()+((size_t)kb*G+g)*cw;for(int l=0;l<32;l++){int8_t stream[128];for(int w=0;w<8;w++){int8_t* x=stream+w*16;int8_t* y=x+8;packet_values(m,g,kb,l,w,0,x);packet_values(m,g,kb,l,w,1,y);if(image==0){uint32_t word=0;for(int j=0;j<8;j++)word|=(dense5::fp4(x[j])|(dense5::fp4(y[j])>>1))<<(4*j);memcpy(p+(w>>2)*512+l*16+(w&3)*4,&word,4);}}if(image==1)dense5::pack_lane(p,l,stream);}}m.image[image]=device(b);}m.t.clear();m.t.shrink_to_fit();}
