float elapsed(const std::function<void()>& f,cudaStream_t st,int calls=3){cudaEvent_t a,b;CU(cudaEventCreate(&a));CU(cudaEventCreate(&b));CU(cudaEventRecord(a,st));for(int i=0;i<calls;i++)f();CU(cudaEventRecord(b,st));CU(cudaEventSynchronize(b));CU(cudaGetLastError());float ms;CU(cudaEventElapsedTime(&ms,a,b));CU(cudaEventDestroy(a));CU(cudaEventDestroy(b));return ms*1000/calls;}
std::vector<float> copy(float* d,int n){std::vector<float> v(n);CU(cudaMemcpy(v.data(),d,n*4,cudaMemcpyDeviceToHost));return v;}
void equal(const std::vector<float>& a,const std::vector<float>& b,const char* arm,int R,const char* phase){size_t bad=0;double mx=0;for(size_t i=0;i<a.size();i++){bad+=memcmp(&a[i],&b[i],4)!=0;mx=std::max(mx,(double)fabs(a[i]-b[i]));if(!std::isfinite(a[i])||!std::isfinite(b[i]))exit(3);}printf("{\"stage\":\"native_correctness\",\"arm\":\"%s\",\"rows\":%d,\"phase\":\"%s\",\"values\":%zu,\"bit_mismatches\":%zu,\"max_abs\":%.9g}\n",arm,R,phase,a.size(),bad,mx);if(bad){fprintf(stderr,"exact same-schedule comparison failed\n");exit(3);}}
